using System.ComponentModel.DataAnnotations;

namespace ShipmentTracker.Data;

public class Shipment
{
    public int Id { get; set; }

    [Required, MaxLength(20)]
    public string TrackingNumber { get; set; } = string.Empty;

    [Required, MaxLength(200)]
    public string Origin { get; set; } = string.Empty;

    [Required, MaxLength(200)]
    public string Destination { get; set; } = string.Empty;

    [Required, MaxLength(50)]
    public string Status { get; set; } = ShipmentStatuses.Pending;

    [Required, MaxLength(200)]
    public string RecipientName { get; set; } = string.Empty;

    [Required, MaxLength(200)]
    public string CustomerEmail { get; set; } = string.Empty;

    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;

    public DateTime? EstimatedDelivery { get; set; }

    public double WeightKg { get; set; }

    [MaxLength(500)]
    public string Notes { get; set; } = string.Empty;
}

public static class ShipmentStatuses
{
    public const string Pending = "Pending";
    public const string PickedUp = "Picked Up";
    public const string InTransit = "In Transit";
    public const string OutForDelivery = "Out for Delivery";
    public const string Delivered = "Delivered";
    public const string Cancelled = "Cancelled";

    public static readonly string[] All =
    [
        Pending, PickedUp, InTransit, OutForDelivery, Delivered, Cancelled
    ];
}

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ShipmentService(HttpClient http)
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync(string? statusFilter = null)
    {
        var url = "api/shipments";
        if (!string.IsNullOrEmpty(statusFilter))
            url += $"?status={Uri.EscapeDataString(statusFilter)}";
        return await http.GetFromJsonAsync<List<ShipmentDto>>(url) ?? [];
    }

    public async Task<List<ShipmentDto>> GetMyShipmentsAsync()
    {
        return await http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments/mine") ?? [];
    }

    public async Task<TrackingResult?> TrackShipmentAsync(string trackingNumber)
    {
        var response = await http.GetAsync($"api/shipments/track/{Uri.EscapeDataString(trackingNumber)}");
        if (!response.IsSuccessStatusCode) return null;
        return await response.Content.ReadFromJsonAsync<TrackingResult>();
    }

    public async Task<ShipmentDto?> CreateShipmentAsync(CreateShipmentRequest request)
    {
        var response = await http.PostAsJsonAsync("api/shipments", request);
        if (!response.IsSuccessStatusCode) return null;
        return await response.Content.ReadFromJsonAsync<ShipmentDto>();
    }

    public async Task<bool> UpdateStatusAsync(int id, UpdateShipmentStatusRequest request)
    {
        var response = await http.PutAsJsonAsync($"api/shipments/{id}/status", request);
        return response.IsSuccessStatusCode;
    }
}

