using System.Security.Claims;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;

namespace ShipmentTracker;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments");

        // Public: track by tracking number
        group.MapGet("track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
            if (shipment is null) return Results.NotFound();
            return Results.Ok(new TrackingResult
            {
                TrackingNumber = shipment.TrackingNumber,
                Origin = shipment.Origin,
                Destination = shipment.Destination,
                Status = shipment.Status,
                RecipientName = shipment.RecipientName,
                CreatedAt = shipment.CreatedAt,
                EstimatedDelivery = shipment.EstimatedDelivery
            });
        });

        // Dispatcher: list all shipments
        group.MapGet("/", async (string? status, ApplicationDbContext db) =>
        {
            var query = db.Shipments.AsQueryable();
            if (!string.IsNullOrEmpty(status))
                query = query.Where(s => s.Status == status);
            var shipments = await query.OrderByDescending(s => s.CreatedAt).ToListAsync();
            return Results.Ok(shipments.Select(ToDto).ToList());
        }).RequireAuthorization("Dispatcher");

        // Customer: list own shipments
        group.MapGet("mine", async (ClaimsPrincipal user, ApplicationDbContext db) =>
        {
            var email = user.FindFirstValue(ClaimTypes.Email) ?? "";
            var shipments = await db.Shipments
                .Where(s => s.CustomerEmail == email)
                .OrderByDescending(s => s.CreatedAt)
                .ToListAsync();
            return Results.Ok(shipments.Select(ToDto).ToList());
        }).RequireAuthorization();

        // Dispatcher: create shipment
        group.MapPost("/", async (CreateShipmentRequest request, ApplicationDbContext db) =>
        {
            var shipment = new Shipment
            {
                TrackingNumber = GenerateTrackingNumber(),
                Origin = request.Origin,
                Destination = request.Destination,
                RecipientName = request.RecipientName,
                CustomerEmail = request.CustomerEmail,
                WeightKg = request.WeightKg,
                EstimatedDelivery = request.EstimatedDelivery,
                Notes = request.Notes,
                CreatedAt = DateTime.UtcNow
            };
            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();
            return Results.Created($"api/shipments/track/{shipment.TrackingNumber}", ToDto(shipment));
        }).RequireAuthorization("Dispatcher");

        // Dispatcher: update status
        group.MapPut("{id}/status", async (int id, UpdateShipmentStatusRequest request, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();
            shipment.Status = request.Status;
