@page "/track"
@rendermode InteractiveAuto
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject ShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g. TRK-20260001)"
                   @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
                @if (isLoading)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Track
            </button>
        </div>
    </div>
</div>

@if (errorMessage is not null)
{
    <div class="alert alert-warning">@errorMessage</div>
}

@if (result is not null)
{
    <div class="card">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>@result.TrackingNumber</strong>
            <span class="badge @GetStatusBadgeClass(result.Status)">@result.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <p><strong>Recipient:</strong> @result.RecipientName</p>
                    <p><strong>Origin:</strong> @result.Origin</p>
                    <p><strong>Destination:</strong> @result.Destination</p>
                </div>
                <div class="col-md-6">
                    <p><strong>Shipped:</strong> @result.CreatedAt.ToString("MMM dd, yyyy")</p>
                    <p><strong>Estimated Delivery:</strong>
                        @(result.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "TBD")
                    </p>
                </div>
            </div>

            @if (result.Status == "Delivered")
            {
                <div class="progress mt-3" style="height: 25px;">
                    <div class="progress-bar bg-success" style="width: 100%">Delivered</div>
                </div>
            }
            else if (result.Status == "Cancelled")
            {
                <div class="alert alert-secondary mt-3 mb-0">This shipment has been cancelled.</div>
            }
            else
            {
                <div class="progress mt-3" style="height: 25px;">
                    <div class="progress-bar" style="width: @(GetProgressPercent(result.Status))%">
                        @result.Status
                    </div>
                </div>
            }
        </div>
    </div>
}

@code {
    private string trackingNumber = "";
    private TrackingResult? result;
    private string? errorMessage;
    private bool isLoading;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await TrackShipment();
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        isLoading = true;
        errorMessage = null;
        result = null;

        result = await ShipmentService.TrackShipmentAsync(trackingNumber.Trim());
        if (result is null)
            errorMessage = $"No shipment found with tracking number \"{trackingNumber.Trim()}\".";

        isLoading = false;
    }

    private static int GetProgressPercent(string status) => status switch
    {
        "Pending" => 10,
        "Picked Up" => 30,
        "In Transit" => 60,
        "Out for Delivery" => 85,
        "Delivered" => 100,
        _ => 0
    };

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "In Transit" => "bg-primary",
        "Out for Delivery" => "bg-info text-dark",
        "Picked Up" => "bg-secondary",
        "Pending" => "bg-warning text-dark",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/dispatcher"
@rendermode InteractiveAuto
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize(Policy = "Dispatcher")]
@inject ShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Dispatcher Dashboard</h1>

<div class="row mb-3">
    <div class="col-md-4">
        <div class="input-group">
            <span class="input-group-text">Filter by status</span>
            <select class="form-select" @bind="statusFilter" @bind:after="LoadShipments">
                <option value="">All</option>
                <option value="Pending">Pending</option>
                <option value="Picked Up">Picked Up</option>
                <option value="In Transit">In Transit</option>
                <option value="Out for Delivery">Out for Delivery</option>
                <option value="Delivered">Delivered</option>
                <option value="Cancelled">Cancelled</option>
            </select>
        </div>
    </div>
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Search by tracking # or destination..."
               @bind="searchText" @bind:event="oninput" />
    </div>
    <div class="col-md-4 text-end">
        <button class="btn btn-success" @onclick="ShowCreateForm">
            + New Shipment
        </button>
        <button class="btn btn-outline-secondary ms-2" @onclick="LoadShipments">
            ↻ Refresh
        </button>
    </div>
</div>

@if (showCreate)
{
    <div class="card mb-4">
        <div class="card-header">Create New Shipment</div>
        <div class="card-body">
            <div class="row g-3">
                <div class="col-md-6">
                    <label class="form-label">Origin</label>
                    <input class="form-control" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Destination</label>
                    <input class="form-control" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Recipient Name</label>
                    <input class="form-control" @bind="newShipment.RecipientName" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Customer Email</label>
                    <input class="form-control" type="email" @bind="newShipment.CustomerEmail" />
                </div>
                <div class="col-md-2">
                    <label class="form-label">Weight (kg)</label>
                    <input class="form-control" type="number" step="0.1" @bind="newShipment.WeightKg" />
                </div>
                <div class="col-md-2">
                    <label class="form-label">Est. Delivery</label>
                    <input class="form-control" type="date" @bind="newShipment.EstimatedDelivery" />
                </div>
                <div class="col-12">
                    <label class="form-label">Notes</label>
                    <textarea class="form-control" @bind="newShipment.Notes"></textarea>
                </div>
                <div class="col-12">
                    <button class="btn btn-primary" @onclick="CreateShipment">Create Shipment</button>
                    <button class="btn btn-outline-secondary ms-2" @onclick="() => showCreate = false">Cancel</button>
                </div>
            </div>
        </div>
    </div>
}

@if (isLoading)
{
    <p><em>Loading shipments...</em></p>
}
else if (filteredShipments.Count == 0)
{
    <div class="alert alert-info">No shipments found.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Recipient</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Weight</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in filteredShipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.RecipientName</td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td>@s.WeightKg.ToString("F1") kg</td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                        <td>
                            @if (editingId == s.Id)
                            {
                                <div class="d-flex gap-1">
                                    <select class="form-select form-select-sm" style="width:auto" @bind="editStatus">
                                        <option value="Pending">Pending</option>
                                        <option value="Picked Up">Picked Up</option>
                                        <option value="In Transit">In Transit</option>
                                        <option value="Out for Delivery">Out for Delivery</option>
                                        <option value="Delivered">Delivered</option>
                                        <option value="Cancelled">Cancelled</option>
                                    </select>
                                    <button class="btn btn-sm btn-success" @onclick="() => SaveStatus(s.Id)">Save</button>
                                    <button class="btn btn-sm btn-outline-secondary" @onclick="() => editingId = null">✕</button>
                                </div>
                            }
                            else
                            {
                                <button class="btn btn-sm btn-outline-primary" @onclick="() => StartEdit(s)">
                                    Update
                                </button>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
    <p class="text-muted">Showing @filteredShipments.Count shipment(s)</p>
}

@code {
    private List<ShipmentDto> shipments = [];
    private string statusFilter = "";
    private string searchText = "";
    private bool isLoading = true;
    private bool showCreate;
    private CreateShipmentRequest newShipment = new();
    private int? editingId;
    private string editStatus = "";

    private List<ShipmentDto> filteredShipments => string.IsNullOrWhiteSpace(searchText)
        ? shipments
        : shipments.Where(s =>
            s.TrackingNumber.Contains(searchText, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(searchText, StringComparison.OrdinalIgnoreCase) ||
            s.RecipientName.Contains(searchText, StringComparison.OrdinalIgnoreCase))
          .ToList();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        shipments = await ShipmentService.GetAllShipmentsAsync(
            string.IsNullOrEmpty(statusFilter) ? null : statusFilter);
        isLoading = false;
    }

    private void ShowCreateForm()
    {
        newShipment = new CreateShipmentRequest { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
        showCreate = true;
    }

    private async Task CreateShipment()
    {
        var created = await ShipmentService.CreateShipmentAsync(newShipment);
