                                <button class="btn btn-sm btn-outline-primary" @onclick="() => StartEdit(s)">
                                    Update
                                </button>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
    <p class="text-muted">Showing @filteredShipments.Count shipment(s)</p>
}

