    <p><em>Loading your shipments...</em></p>
}
else if (filteredShipments.Count == 0)
{
    <div class="alert alert-info">
        No shipments found for your account.
        <a href="track" class="alert-link">Track a shipment by number</a> instead.
    </div>
}
else
{
    <div class="row">
        @foreach (var s in filteredShipments)
        {
            <div class="col-md-6 col-lg-4 mb-3">
