                        <p class="mb-1"><strong>From:</strong> @s.Origin</p>
                        <p class="mb-1"><strong>To:</strong> @s.Destination</p>
                        <p class="mb-1"><strong>Weight:</strong> @s.WeightKg.ToString("F1") kg</p>
                        <hr />
                        <p class="mb-1"><strong>Shipped:</strong> @s.CreatedAt.ToString("MMM dd, yyyy")</p>
                        <p class="mb-0">
                            <strong>Est. Delivery:</strong>
                            @if (s.EstimatedDelivery.HasValue)
                            {
                                var daysLeft = (s.EstimatedDelivery.Value - DateTime.UtcNow).Days;
                                <span>
                                    @s.EstimatedDelivery.Value.ToString("MMM dd, yyyy")
                                    @if (s.Status != "Delivered" && s.Status != "Cancelled")
                                    {
                                        if (daysLeft > 0)
                                        {
                                            <span class="text-muted">(@daysLeft day(s) away)</span>
                                        }
                                        else if (daysLeft == 0)
                                        {
                                            <span class="text-success">(Today!)</span>
                                        }
                                        else
                                        {
                                            <span class="text-danger">(Overdue)</span>
                                        }
                                    }
                                </span>
                            }
                            else
                            {
                                <span class="text-muted">TBD</span>
                            }
                        </p>
                    </div>
                    <div class="card-footer">
                        @if (s.Status is "Delivered")
                        {
                            <div class="progress" style="height: 20px;">
                                <div class="progress-bar bg-success" style="width: 100%">Delivered ✓</div>
                            </div>
                        }
                        else if (s.Status is "Cancelled")
                        {
                            <span class="text-muted">Cancelled</span>
                        }
                        else
                        {
                            <div class="progress" style="height: 20px;">
                                <div class="progress-bar" style="width: @(GetProgressPercent(s.Status))%">
                                    @s.Status
                                </div>
                            </div>
                        }
                    </div>
                </div>
            </div>
        }
    </div>
