        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g. TRK-20260001)"
                   @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
                @if (isLoading)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Track
            </button>
        </div>
    </div>
</div>

@if (errorMessage is not null)
{
    <div class="alert alert-warning">@errorMessage</div>
}

@if (result is not null)
{
    <div class="card">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>@result.TrackingNumber</strong>
            <span class="badge @GetStatusBadgeClass(result.Status)">@result.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
