                </div>
                <div class="col-md-6">
                    <p><strong>Shipped:</strong> @result.CreatedAt.ToString("MMM dd, yyyy")</p>
                    <p><strong>Estimated Delivery:</strong>
                        @(result.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "TBD")
                    </p>
                </div>
            </div>

            @if (result.Status == "Delivered")
            {
                <div class="progress mt-3" style="height: 25px;">
                    <div class="progress-bar bg-success" style="width: 100%">Delivered</div>
                </div>
            }
            else if (result.Status == "Cancelled")
            {
                <div class="alert alert-secondary mt-3 mb-0">This shipment has been cancelled.</div>
            }
            else
            {
                <div class="progress mt-3" style="height: 25px;">
                    <div class="progress-bar" style="width: @(GetProgressPercent(result.Status))%">
                        @result.Status
                    </div>
                </div>
            }
        </div>
    </div>
}

@code {
    private string trackingNumber = "";
    private TrackingResult? result;
    private string? errorMessage;
    private bool isLoading;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await TrackShipment();
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        isLoading = true;
        errorMessage = null;
        result = null;

        result = await ShipmentService.TrackShipmentAsync(trackingNumber.Trim());
        if (result is null)
            errorMessage = $"No shipment found with tracking number \"{trackingNumber.Trim()}\".";

        isLoading = false;
    }

    private static int GetProgressPercent(string status) => status switch
    {
        "Pending" => 10,
        "Picked Up" => 30,
        "In Transit" => 60,
        "Out for Delivery" => 85,
        "Delivered" => 100,
        _ => 0
    };

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "In Transit" => "bg-primary",
        "Out for Delivery" => "bg-info text-dark",
        "Picked Up" => "bg-secondary",
        "Pending" => "bg-warning text-dark",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

