@page "/my-shipments"
@rendermode InteractiveAuto
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject ShipmentService ShipmentService

<PageTitle>My Shipments</PageTitle>

<h1>My Shipments</h1>
<p class="text-muted">Showing shipments associated with your account email.</p>

<div class="row mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Filter by tracking # or destination..."
               @bind="searchText" @bind:event="oninput" />
    </div>
    <div class="col-md-2">
        <button class="btn btn-outline-secondary" @onclick="LoadShipments">↻ Refresh</button>
    </div>
</div>

@if (isLoading)
{
    <p><em>Loading your shipments...</em></p>
}
else if (filteredShipments.Count == 0)
{
    <div class="alert alert-info">
        No shipments found for your account.
        <a href="track" class="alert-link">Track a shipment by number</a> instead.
    </div>
}
else
{
    <div class="row">
        @foreach (var s in filteredShipments)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card h-100">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <code>@s.TrackingNumber</code>
                        <span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span>
                    </div>
                    <div class="card-body">
                        <p class="mb-1"><strong>From:</strong> @s.Origin</p>
                        <p class="mb-1"><strong>To:</strong> @s.Destination</p>
                        <p class="mb-1"><strong>Weight:</strong> @s.WeightKg.ToString("F1") kg</p>
                        <hr />
                        <p class="mb-1"><strong>Shipped:</strong> @s.CreatedAt.ToString("MMM dd, yyyy")</p>
                        <p class="mb-0">
                            <strong>Est. Delivery:</strong>
                            @if (s.EstimatedDelivery.HasValue)
                            {
                                var daysLeft = (s.EstimatedDelivery.Value - DateTime.UtcNow).Days;
                                <span>
                                    @s.EstimatedDelivery.Value.ToString("MMM dd, yyyy")
                                    @if (s.Status != "Delivered" && s.Status != "Cancelled")
                                    {
                                        if (daysLeft > 0)
                                        {
                                            <span class="text-muted">(@daysLeft day(s) away)</span>
                                        }
                                        else if (daysLeft == 0)
                                        {
                                            <span class="text-success">(Today!)</span>
                                        }
                                        else
                                        {
                                            <span class="text-danger">(Overdue)</span>
                                        }
                                    }
                                </span>
                            }
                            else
                            {
                                <span class="text-muted">TBD</span>
                            }
                        </p>
                    </div>
                    <div class="card-footer">
                        @if (s.Status is "Delivered")
                        {
                            <div class="progress" style="height: 20px;">
                                <div class="progress-bar bg-success" style="width: 100%">Delivered ✓</div>
                            </div>
                        }
                        else if (s.Status is "Cancelled")
                        {
                            <span class="text-muted">Cancelled</span>
                        }
                        else
                        {
                            <div class="progress" style="height: 20px;">
                                <div class="progress-bar" style="width: @(GetProgressPercent(s.Status))%">
                                    @s.Status
                                </div>
                            </div>
                        }
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private List<ShipmentDto> shipments = [];
    private string searchText = "";
    private bool isLoading = true;

    private List<ShipmentDto> filteredShipments => string.IsNullOrWhiteSpace(searchText)
        ? shipments
        : shipments.Where(s =>
            s.TrackingNumber.Contains(searchText, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(searchText, StringComparison.OrdinalIgnoreCase))
          .ToList();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        shipments = await ShipmentService.GetMyShipmentsAsync();
        isLoading = false;
    }

    private static int GetProgressPercent(string status) => status switch
    {
        "Pending" => 10,
        "Picked Up" => 30,
        "In Transit" => 60,
        "Out for Delivery" => 85,
        "Delivered" => 100,
        _ => 0
    };

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "In Transit" => "bg-primary",
        "Out for Delivery" => "bg-info text-dark",
        "Picked Up" => "bg-secondary",
        "Pending" => "bg-warning text-dark",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

